async function getAdminConfigNumber(
  supabase: ReturnType<typeof createClient>,
  key: string,
): Promise<number> {
  const { data, error } = await supabase
    .from('admin_config')
    .select('value')
    .eq('key', key)
    .eq('is_active', true)
    .single();

  if (error || !data) {
